SRC = r'''
__device__ __forceinline__ float silu_bw(float g, float x, float s) {
    return __fmul_rn(g, __fmul_rn(s, __fadd_rn(1.0f, __fmul_rn(x, __fsub_rn(1.0f, s)))));
}
__device__ __forceinline__ float4 ld4(const float* p, unsigned long long pol) {
    float4 v; asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x), "=f"(v.y), "=f"(v.z), "=f"(v.w) : "l"(p), "l"(pol)); return v; }
__device__ __forceinline__ void st4(float* p, float4 v, unsigned long long pol) {
    asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p), "f"(v.x), "f"(v.y), "f"(v.z), "f"(v.w), "l"(pol) : "memory"); }
extern "C" __global__ void k(const float* __restrict__ g, const float* __restrict__ x, const float* __restrict__ s, float* __restrict__ o, unsigned n) {
    const unsigned nvec = n >> 2;
    const unsigned i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < nvec) {
        float4 a = ld4(g + 4*i, 0x12F0000000000000ull), b = ld4(x + 4*i, 0x12F0000000000000ull), c = ld4(s + 4*i, 0x12F0000000000000ull);
        float4 r; r.x = silu_bw(a.x,b.x,c.x); r.y = silu_bw(a.y,b.y,c.y); r.z = silu_bw(a.z,b.z,c.z); r.w = silu_bw(a.w,b.w,c.w);
        st4(o + 4*i, r, 0x14F0000000000000ull);
    } else if (i == nvec) {
        const unsigned e = nvec << 2; float ta[3], tb[3], tc[3];
        #pragma unroll
        for (int q = 0; q < 3; ++q) if (e + q < n) { ta[q] = g[e+q]; tb[q] = x[e+q]; tc[q] = s[e+q]; }
        #pragma unroll
        for (int q = 0; q < 3; ++q) if (e + q < n) o[e+q] = silu_bw(ta[q], tb[q], tc[q]);
    }
}'''
