    cfgs = {}
    def get(n):
        if n in cfgs: return cfgs[n]
        nt = (n >> 2) + (1 if n & 3 else 0)
        grid = (nt + T - 1) // T
        if C: grid = (grid + C - 1) // C * C
        cfg = D.CUlaunchConfig(); cfg.gridDimX, cfg.gridDimY, cfg.gridDimZ = grid, 1, 1
        cfg.blockDimX, cfg.blockDimY, cfg.blockDimZ = T, 1, 1; cfg.sharedMemBytes = 0
        al = []
        if C:
            a = D.CUlaunchAttribute(); a.id = A.CU_LAUNCH_ATTRIBUTE_CLUSTER_DIMENSION
            a.value.clusterDim.x, a.value.clusterDim.y, a.value.clusterDim.z = C, 1, 1; al.append(a)
        if coop:
            a = D.CUlaunchAttribute(); a.id = A.CU_LAUNCH_ATTRIBUTE_COOPERATIVE; a.value.cooperative = 1; al.append(a)
        cfg.attrs = al; cfg.numAttrs = len(al); cfgs[n] = cfg; return cfg
    def launch(g, x, s, o):
        n = g.numel(); cfg = get(n)
        cfg.hStream = D.CUstream(torch.cuda.current_stream().cuda_stream)
        args = ((g.data_ptr(), x.data_ptr(), s.data_ptr(), o.data_ptr(), n), (ctypes.c_void_p,)*4 + (ctypes.c_uint32,))
        err, = D.cuLaunchKernelEx(cfg, K.fn, args, 0); assert int(err) == 0, err
