     "C1coop": mk(256,1,True), "C16coop": mk(256,16,True), "C1_t128": mk(128,1), "C16_t64": mk(64,16)}
# correctness
for n in (131, 4096):
    g,x,s = (torch.randn(n, device="cuda") for _ in range(3)); ref = g*(s*(1+x*(1-s)))
    for nm,f in V.items():
        o = torch.zeros(n, device="cuda"); f(g,x,s,o); torch.cuda.synchronize(); assert torch.equal(o, ref), (nm, n)
sizes = [131, 2053, 4096, 16384]
res = {(nm,n): [] for nm in V for n in sizes}
data = {n: [torch.randn(n, device="cuda") for _ in range(3)] + [torch.zeros(n, device="cuda")] for n in sizes}
for r in range(9):
    for n in sizes:
        g,x,s,o = data[n]
