extern "C" void silu_bw_launch(const float* g, const float* x, const float* s, float* o, long long n,
                               cudaStream_t stream) {
    if (n <= 0) return;
    static unsigned long long coop_max = 0;      // one-wave cooperative limit, from the compiled kernel's occupancy
    if (coop_max == 0) {
